/// Helper to create a test workspace with a clean checkpoint
fn create_forkable_workspace() -> (TempDir, WorkspaceConfig, Connection) {
    let temp_dir = TempDir::new().unwrap();
    let root = temp_dir.path();

    // Create .beads directory structure
    let beads_dir = root.join(".beads");
    std::fs::create_dir_all(&beads_dir).unwrap();

    // Create checkpoint directory
    let checkpoint_dir = beads_dir.join("checkpoint");
    std::fs::create_dir_all(&checkpoint_dir).unwrap();

    // Initialize workspace
    let config = SqliteStore::new()
        .init_workspace("test-prefix")
        .unwrap();

    // Open database connection
    let db_path = config.database_path();
    let conn = Connection::open(&db_path).unwrap();

    // Enable foreign keys
    conn.execute("PRAGMA foreign_keys = ON", []).unwrap();

    // Initialize checkpoint state (simulate clean checkpoint)
    // Use INSERT OR REPLACE to handle if it already exists
    conn.execute(
        "INSERT OR REPLACE INTO checkpoint_state (id, covered_event_sequence, current_generation_id, updated_at)
         VALUES (1, 0, 'gen-001', datetime('now'))",
        [],
    )
    .unwrap();

    (temp_dir, config, conn)
}

